        <Link href="/" className="flex items-center gap-3 text-[#3b1f2b] no-underline"><span className="grid h-10 w-10 place-items-center rounded-full bg-[#3b1f2b] text-[#c9a66b]"><Scissors size={19} /></span><span><span className="block font-display text-xl leading-none">Romi Salon</span><span className="mt-1 block text-[9px] tracking-[.23em] text-[#9a7a56]">RAWAT • TENANG • BERSAMA</span></span></Link>
