        <div className="relative mt-14 hidden h-[390px] items-center justify-center lg:flex"><div className="absolute right-[8%] top-[5%] h-[320px] w-[280px] rotate-3 rounded-[48%_48%_25%_25%] border border-[#d1b685]/50 bg-[radial-gradient(ellipse_at_35%_30%,#c7a78f_0%,#8a5c5b_28%,#492a38_70%)] shadow-2xl" /><div className="absolute right-[22%] top-[16%] h-[255px] w-[170px] rounded-[50%_48%_30%_30%] bg-[linear-gradient(125deg,rgba(255,227,193,.38),rgba(102,58,68,.18)_44%,rgba(37,21,30,.75))] shadow-inner" /><div className="absolute bottom-7 left-7 rounded-2xl border border-[#e5c790]/25 bg-[#3b1f2b]/75 p-5 backdrop-blur"><div className="eyebrow text-[#d5b77f]">Ruang jeda</div><div className="mt-2 font-display text-2xl">Sentuhan ahli.</div><div className="mt-1 text-xs text-[#eadcc9]/70">Hasil yang tetap terasa seperti kamu.</div></div></div>
