function BookingDialog({ service, onClose }: { service: SalonService; onClose: () => void }) {
  const { data: user } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  const [date, setDate] = useState(todayJakarta());
  const params = { serviceId: service.id, date };
  const slots = useGetAvailableSlots(params, { query: { queryKey: getGetAvailableSlotsQueryKey(params), enabled: !!service.id } });
  const create = useCreateBooking();
  const payment = useCompleteMockPayment();
  const qc = useQueryClient();
  const [, setPath] = useLocation();
  const [selected, setSelected] = useState('');
  const [created, setCreated] = useState<Booking | null>(null);
  const [message, setMessage] = useState('');
  const book = () => {
    if (!user) { setPath('/login'); return; }
    if (!selected) { setMessage('Pilih salah satu waktu yang tersedia.'); return; }
    create.mutate({ data: { serviceId: service.id, startTime: `${date}T${selected}:00+07:00` } }, { onSuccess: (booking) => { setCreated(booking); qc.invalidateQueries({ queryKey: getGetMemberDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminBookingsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }); }, onError: () => setMessage('Jadwal belum berhasil dipesan. Silakan coba kembali.') });
  };
  const pay = () => created && payment.mutate({ bookingId: created.id }, { onSuccess: (r) => { setMessage(r.message); qc.invalidateQueries({ queryKey: getGetMemberDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }); }, onError: () => setMessage('Pembayaran demo belum berhasil. Coba kembali.') });
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#25131c]/65 p-4" role="dialog" aria-modal="true" aria-labelledby="booking-title"><div className="max-h-[90dvh] w-full max-w-xl overflow-y-auto rounded-3xl bg-[#faf6f0] p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between gap-4"><div><div className="eyebrow">Buat reservasi</div><h2 id="booking-title" className="mt-2 font-display text-3xl text-[#3b1f2b]">{created ? 'Reservasi tercatat' : service.name}</h2><p className="mt-2 text-sm text-[#78696a]">{created ? `Kode booking: ${created.bookingCode}` : `${service.durationMin} menit · ${rupiah(service.price)}`}</p></div><button data-testid="button-close-booking" onClick={onClose} className="rounded-full p-2 text-[#6d595e]" aria-label="Tutup"><X /></button></div>
    {created ? <div className="mt-7 rounded-2xl bg-[#f0e8de] p-5"><p className="text-sm leading-6 text-[#68575a]">Status reservasi: <b>{statusId(created.status)}</b>. {message}</p>{created.paymentStatus !== 'PAID' && <Action className="mt-5 w-full" kind="gold" onClick={pay} disabled={payment.isPending}><CreditCard size={16} />{payment.isPending ? 'Memproses pembayaran…' : 'Bayar demo melalui server'}</Action>}{message && <div className="mt-3 text-sm font-medium text-[#4d7651]">{message}</div>}</div> :
    <div className="mt-7 grid gap-5"><Field label="Tanggal kunjungan" type="date" min={todayJakarta()} value={date} onChange={(e) => { setDate(e.target.value); setSelected(''); }} />{slots.isLoading ? <Loader label="Memuat waktu tersedia" /> : slots.isError ? <Notice retry={() => void slots.refetch()}>Waktu yang tersedia belum dapat dimuat.</Notice> : (slots.data?.slots || []).length ? <div><div className="mb-3 text-sm font-semibold">Pilih waktu (WIB)</div><div className="grid grid-cols-3 gap-2 sm:grid-cols-4">{slots.data?.slots.map((slot) => <button key={slot} data-testid={`slot-${slot}`} onClick={() => setSelected(slot)} className={cx('rounded-xl border px-3 py-3 text-sm transition', selected === slot ? 'border-[#3b1f2b] bg-[#3b1f2b] text-white' : 'border-[#dfd3c4] bg-[#fffdfa] text-[#503f45] hover:border-[#c9a66b]')}>{slot}</button>)}</div></div> : <div className="rounded-xl bg-[#f0e8de] p-4 text-sm text-[#756568]">Tidak ada waktu tersedia di tanggal ini. Silakan pilih tanggal lain.</div>}{message && !created && <div className="text-sm text-[#b5524a]">{message}</div>}<Action className="w-full" onClick={book} disabled={create.isPending}>{create.isPending ? 'Menyimpan reservasi…' : user ? 'Konfirmasi reservasi' : 'Masuk untuk melanjutkan'} <ArrowRight size={16} /></Action><p className="text-center text-xs text-[#88797a]">Pembayaran demo hanya dianggap berhasil jika dikonfirmasi oleh server.</p></div>}</div></div>;
}

function AuthPage({ mode }: { mode: 'login' | 'register' }) {
  const login = useLogin(); const register = useRegisterMember(); const qc = useQueryClient(); const [, setPath] = useLocation();
  const [error, setError] = useState('');
  const [values, setValues] = useState({ name: '', email: '', phone: '', password: '' });
  const update = (k: string, v: string) => setValues((x) => ({ ...x, [k]: v }));
  const submit = (e: FormEvent) => {
    e.preventDefault(); setError('');
    const success = (user: { role: string }) => { qc.setQueryData(getGetCurrentUserQueryKey(), user); setPath(user.role === 'ADMIN' ? '/admin' : '/member'); };
    if (mode === 'register') register.mutate({ data: values }, { onSuccess: success, onError: () => setError('Pendaftaran belum berhasil. Periksa kembali data yang kamu masukkan.') });
    else login.mutate({ data: { email: values.email, password: values.password } }, { onSuccess: success, onError: () => setError('Email atau kata sandi belum sesuai.') });
  };
  const busy = login.isPending || register.isPending;
  return <Shell><main className="mx-auto grid min-h-[calc(100dvh-150px)] max-w-7xl items-center gap-10 px-5 py-12 lg:grid-cols-[1fr_.8fr] lg:px-8"><div className="hidden rounded-[2rem] bg-[#3b1f2b] p-12 text-[#faf6f0] lg:block"><div className="eyebrow text-[#d5b77f]">Romi Circle</div><h1 className="mt-5 font-display text-5xl leading-tight">{mode === 'register' ? 'Perawatan yang baik terasa lebih baik bersama.' : 'Senang bertemu lagi.'}</h1><p className="mt-6 max-w-md leading-7 text-[#f0e6da]/75">Kelola kunjunganmu, lihat progres membership, dan temukan manfaat yang tumbuh seiring waktumu bersama Romi.</p><div className="mt-14 flex gap-3 text-[#d9c79e]"><Sparkles /><span className="text-sm">Waktu untukmu, dengan perhatian penuh.</span></div></div><section className="mx-auto w-full max-w-md"><div className="eyebrow">{mode === 'register' ? 'Bergabung dengan Romi Circle' : 'Romi Salon'}</div><h2 className="mt-3 font-display text-4xl text-[#3b1f2b]">{mode === 'register' ? 'Mulai perjalananmu.' : 'Masuk ke akunmu.'}</h2><p className="mt-3 text-sm leading-6 text-[#7b6b6d]">{mode === 'register' ? 'Buat akun untuk memesan jadwal dan mengumpulkan manfaat.' : 'Lanjutkan perjalanan perawatanmu bersama kami.'}</p>
      <form onSubmit={submit} className="mt-8 grid gap-4">{mode === 'register' && <><Field label="Nama lengkap" autoComplete="name" required minLength={2} value={values.name} onChange={(e) => update('name', e.target.value)} /><Field label="Nomor telepon" type="tel" autoComplete="tel" required minLength={8} value={values.phone} onChange={(e) => update('phone', e.target.value)} /></>}<Field label="Alamat email" type="email" autoComplete="email" required value={values.email} onChange={(e) => update('email', e.target.value)} /><Field label="Kata sandi" type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} required minLength={8} value={values.password} onChange={(e) => update('password', e.target.value)} />{error && <div role="alert" className="rounded-xl bg-[#f8e7e2] p-3 text-sm text-[#994a45]">{error}</div>}<Action type="submit" className="mt-2 w-full" disabled={busy}>{busy ? 'Memproses…' : mode === 'register' ? 'Buat akun member' : 'Masuk'} <ArrowRight size={16} /></Action></form>
      <div className="mt-6 text-center text-sm text-[#76676a]">{mode === 'register' ? 'Sudah menjadi member?' : 'Belum menjadi member?'} <Link href={mode === 'register' ? '/login' : '/register'} className="font-semibold text-[#8a6340]">{mode === 'register' ? 'Masuk' : 'Daftar di sini'}</Link></div>
      {mode === 'login' && <div className="mt-8 rounded-2xl border border-[#e5d9cb] bg-[#f4ede3] p-4"><div className="text-xs font-bold uppercase tracking-[.14em] text-[#96734b]">Akun demo</div><div className="mt-3 grid gap-2 text-xs text-[#69585d] sm:grid-cols-2"><button data-testid="demo-admin" className="rounded-lg bg-[#faf6f0] p-3 text-left hover:bg-white" onClick={() => setValues({ name: '', email: 'admin@romisalon.id', phone: '', password: 'RomiAdmin2026!' })}><b>Admin</b><br />admin@romisalon.id</button><button data-testid="demo-member" className="rounded-lg bg-[#faf6f0] p-3 text-left hover:bg-white" onClick={() => setValues({ name: '', email: 'member@romisalon.id', phone: '', password: 'RomiMember2026!' })}><b>Member</b><br />member@romisalon.id</button></div><p className="mt-2 text-[10px] leading-4 text-[#88797a]">Klik akun untuk mengisi kredensial demo yang disediakan server.</p></div>}</section></main></Shell>;
}

function MemberPage() {
  const dash = useGetMemberDashboard({ query: { queryKey: getGetMemberDashboardQueryKey(), retry: false } });
  const cancel = useCancelMemberBooking(); const payment = useCompleteMockPayment(); const update = useUpdateMemberProfile(); const changePassword = useUpdateMemberPassword(); const qc = useQueryClient();
  const [, setPath] = useLocation(); const [editing, setEditing] = useState(false); const [notice, setNotice] = useState('');
  const [name, setName] = useState(''); const [phone, setPhone] = useState('');
  const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordFeedback, setPasswordFeedback] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  if (dash.isLoading) return <Shell><main className="mx-auto max-w-7xl px-5 py-12"><Loader /></main></Shell>;
  if (dash.isError || !dash.data) return <Shell><main className="mx-auto max-w-2xl px-5 py-16"><Notice retry={() => void dash.refetch()}>Masuk sebagai member untuk membuka ruang pribadimu.</Notice><div className="mt-4 text-center"><Action onClick={() => setPath('/login')}>Masuk ke akun</Action></div></main></Shell>;
  const d = dash.data; const target = d.nextLevel?.minSpending ?? d.level.minSpending; const progress = d.nextLevel ? Math.min(100, Math.round((d.totalSpending / target) * 100)) : 100;
  const startEdit = () => { setName(d.user.name); setPhone(d.user.phone); setEditing(true); };
  const save = (e: FormEvent) => { e.preventDefault(); update.mutate({ data: { name, phone } }, { onSuccess: () => { setEditing(false); setNotice('Profil berhasil diperbarui.'); qc.invalidateQueries({ queryKey: getGetMemberDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetCurrentUserQueryKey() }); }, onError: () => setNotice('Profil belum berhasil disimpan.') }); };
  const savePassword = (e: FormEvent) => {
    e.preventDefault();
    setPasswordFeedback(null);
    if (newPassword !== confirmPassword) { setPasswordFeedback({ type: 'error', text: 'Konfirmasi kata sandi baru belum sama.' }); return; }
    changePassword.mutate({ data: { currentPassword, newPassword } }, {
      onSuccess: () => {
        setCurrentPassword(''); setNewPassword(''); setConfirmPassword('');
        setPasswordFeedback({ type: 'success', text: 'Kata sandi berhasil diperbarui.' });
      },
      onError: () => setPasswordFeedback({ type: 'error', text: 'Kata sandi saat ini tidak sesuai atau perubahan belum berhasil. Silakan coba kembali.' }),
    });
  };
  const doPay = (b: Booking) => payment.mutate({ bookingId: b.id }, { onSuccess: (r) => { setNotice(r.message); qc.invalidateQueries({ queryKey: getGetMemberDashboardQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminTransactionsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminDashboardQueryKey() }); }, onError: () => setNotice('Pembayaran demo belum berhasil.') });
  return <Shell><main className="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">Romi Circle / Ruang member</div><h1 className="mt-2 font-display text-4xl text-[#3b1f2b]">Selamat datang, {d.user.name.split(' ')[0]}.</h1><p className="mt-2 text-sm text-[#78696a]">Waktu untuk dirimu, tersusun dalam satu tempat.</p></div><Action kind="outline" onClick={startEdit}><Pencil size={15} /> Edit profil</Action></div>
    <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="relative overflow-hidden rounded-3xl bg-[#3b1f2b] p-7 text-[#faf6f0] shadow-lg sm:p-9"><div className="absolute -right-10 -top-16 h-64 w-64 rounded-full border border-[#c9a66b]/20" /><div className="absolute -right-1 -top-6 h-44 w-44 rounded-full border border-[#c9a66b]/20" /><div className="relative flex items-start justify-between"><div><div className="text-xs tracking-[.18em] text-[#d4b67f]">ROMI CIRCLE MEMBER</div><h2 className="mt-3 font-display text-4xl">{d.level.name}</h2><div className="mt-2 text-sm text-[#f0e6da]/75">Terdaftar sebagai {d.user.name}</div></div><div className="grid h-12 w-12 place-items-center rounded-full border border-[#d6b77e]/50 text-[#d6b77e]"><Crown /></div></div><div className="relative mt-12 grid grid-cols-2 gap-5 border-t border-white/15 pt-5"><div><div className="text-xs text-[#f0e6da]/65">Total perawatan</div><div className="mt-1 font-display text-2xl">{rupiah(d.totalSpending)}</div></div><div><div className="text-xs text-[#f0e6da]/65">Poin terkumpul</div><div className="mt-1 font-display text-2xl">{d.points.toLocaleString('id-ID')} poin</div></div></div></section>
      <section className="soft-card p-7"><div className="flex items-center justify-between"><div><div className="eyebrow">Progres berikutnya</div><h2 className="mt-2 font-display text-2xl">{d.nextLevel ? d.nextLevel.name : 'Level terbaik tercapai'}</h2></div><span className="grid h-11 w-11 place-items-center rounded-full bg-[#f1e6d4] text-[#a57d48]"><Gem /></span></div><div className="mt-7 h-3 overflow-hidden rounded-full bg-[#eee5da]"><div className="h-full rounded-full bg-[#c9a66b] transition-all" style={{ width: `${progress}%` }} /></div><div className="mt-3 flex justify-between text-xs text-[#867679]"><span>{rupiah(d.totalSpending)} terkumpul</span><span>{d.nextLevel ? rupiah(d.nextLevel.minSpending) : '100%'}</span></div><p className="mt-5 text-sm text-[#736467]">{d.nextLevel ? `Teruskan perawatanmu — ${d.pointsToNextLevel.toLocaleString('id-ID')} poin lagi untuk langkah berikutnya.` : 'Seluruh manfaat Romi Circle kini menjadi milikmu.'}</p><div className="mt-5 flex flex-wrap gap-2">{d.level.benefits.map((b) => <span key={b} className="rounded-full bg-[#f5eee4] px-3 py-2 text-xs text-[#6e555a]">{b}</span>)}</div></section></div>
    <section className="soft-card mt-8 p-6 sm:p-8">
      <div className="grid gap-7 lg:grid-cols-[.7fr_1fr] lg:items-start">
        <div><div className="eyebrow">Keamanan akun</div><h2 className="mt-2 font-display text-3xl text-[#3b1f2b]">Perbarui kata sandi.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[#78696a]">Gunakan kata sandi baru yang berbeda dan mudah kamu ingat. Minimal delapan karakter.</p></div>
        <form onSubmit={savePassword} className="grid gap-4 sm:grid-cols-2">
          <Field label="Kata sandi saat ini" type="password" autoComplete="current-password" required minLength={8} value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} className="sm:col-span-2" />
          <Field label="Kata sandi baru" type="password" autoComplete="new-password" required minLength={8} value={newPassword} onChange={(e) => setNewPassword(e.target.value)} />
          <Field label="Konfirmasi kata sandi baru" type="password" autoComplete="new-password" required minLength={8} value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} />
          {passwordFeedback && <div role={passwordFeedback.type === 'error' ? 'alert' : 'status'} className={cx('rounded-xl p-3 text-sm sm:col-span-2', passwordFeedback.type === 'success' ? 'bg-[#e6eee5] text-[#486d4b]' : 'bg-[#f8e7e2] text-[#994a45]')}>{passwordFeedback.text}</div>}
          <div className="sm:col-span-2"><Action type="submit" disabled={changePassword.isPending}>{changePassword.isPending ? 'Menyimpan kata sandi…' : 'Simpan kata sandi'}</Action>{changePassword.isPending && <p role="status" aria-live="polite" className="mt-2 text-sm text-[#78696a]">Perubahan kata sandi sedang diproses dengan aman.</p>}</div>
        </form>
      </div>
    </section>
    {notice && <div role="status" className="mt-5 rounded-xl bg-[#e6eee5] p-3 text-sm text-[#486d4b]">{notice}</div>}
    <div className="mt-10 grid gap-8 lg:grid-cols-[1.15fr_.85fr]"><section><SectionTitle eyebrow="Jadwalmu" title="Kunjungan mendatang." /><div className="grid gap-3">{d.bookings.length ? d.bookings.map((b) => <article key={b.id} className="soft-card flex flex-col justify-between gap-4 p-5 sm:flex-row sm:items-center"><div><div className="font-semibold text-[#3b1f2b]">{b.serviceName}</div><div className="mt-1 text-xs text-[#817174]">{dateId(b.startTime)} · {b.bookingCode}</div><div className="mt-2 text-xs">Status: <b>{statusId(b.status)}</b> · Pembayaran: <b>{statusId(b.paymentStatus)}</b></div></div><div className="flex flex-wrap gap-2">{b.paymentStatus !== 'PAID' && b.status !== 'CANCELLED' && <Action kind="gold" onClick={() => doPay(b)} disabled={payment.isPending}><CreditCard size={14} />Bayar demo</Action>}{b.status !== 'CANCELLED' && b.status !== 'COMPLETED' && <Action kind="outline" onClick={() => cancel.mutate({ bookingId: b.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getGetMemberDashboardQueryKey() }), onError: () => setNotice('Reservasi belum dapat dibatalkan.') })} disabled={cancel.isPending}>Batalkan</Action>}</div></article>) : <div className="soft-card p-7 text-sm text-[#76676a]">Belum ada reservasi. Kunjungan berikutnya bisa dimulai kapan saja.</div>}</div></section><section><SectionTitle eyebrow="Riwayat" title="Transaksi." /><div className="soft-card overflow-hidden">{d.transactions.length ? d.transactions.map((t) => <div key={t.id} className="flex items-center justify-between gap-3 border-b border-[#eee4d8] p-4 last:border-0"><div><div className="text-sm font-semibold">{t.serviceName}</div><div className="mt-1 text-xs text-[#867679]">{dateId(t.createdAt)} · {statusId(t.status)}</div></div><div className="text-sm font-semibold">{rupiah(t.finalAmount)}</div></div>) : <div className="p-7 text-sm text-[#76676a]">Riwayat transaksi akan tampil di sini.</div>}</div><div className="mt-6 rounded-2xl bg-[#f0e8de] p-5"><div className="eyebrow">Pembaruan Romi</div>{d.notifications.length ? d.notifications.map((n, i) => <p key={i} className="mt-3 text-sm leading-6 text-[#69585d]">{n}</p>) : <p className="mt-3 text-sm text-[#69585d]">Belum ada kabar baru.</p>}</div></section></div></main>{editing && <div role="dialog" aria-modal="true" className="fixed inset-0 z-50 grid place-items-center bg-[#25131c]/60 p-4"><form onSubmit={save} className="grid w-full max-w-md gap-4 rounded-3xl bg-[#faf6f0] p-7"><div className="flex justify-between"><h2 className="font-display text-3xl">Edit profil</h2><button type="button" onClick={() => setEditing(false)} aria-label="Tutup"><X /></button></div><Field label="Nama lengkap" required minLength={2} value={name} onChange={(e) => setName(e.target.value)} /><Field label="Nomor telepon" required minLength={8} value={phone} onChange={(e) => setPhone(e.target.value)} /><Action type="submit" disabled={update.isPending}>{update.isPending ? 'Menyimpan…' : 'Simpan perubahan'}</Action></form></div>}</Shell>;
}

function AdminPage() {
  const { data: user, isLoading: userLoading } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  const [, setPath] = useLocation(); const [tab, setTab] = useState('overview'); const [search, setSearch] = useState(''); const [dateFilter, setDateFilter] = useState(''); const [modal, setModal] = useState<{ kind: 'service' | 'level'; item?: SalonService | MembershipLevel } | null>(null); const [message, setMessage] = useState('');
  const qc = useQueryClient();
  const dash = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey(), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const services = useGetAdminServices({ query: { queryKey: getGetAdminServicesQueryKey(), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const levels = useGetMembershipLevels({ query: { queryKey: getGetMembershipLevelsQueryKey(), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const params = { search: search || undefined }; const members = useGetAdminMembers(params, { query: { queryKey: getGetAdminMembersQueryKey(params), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const bparams = { date: dateFilter || undefined }; const bookings = useGetAdminBookings(bparams, { query: { queryKey: getGetAdminBookingsQueryKey(bparams), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const transactions = useGetAdminTransactions({ query: { queryKey: getGetAdminTransactionsQueryKey(), enabled: !!user && user.role === 'ADMIN', retry: false } });
  const addService = useCreateService(); const editService = useUpdateService(); const delService = useDeleteService();
  const addLevel = useCreateMembershipLevel(); const editLevel = useUpdateMembershipLevel(); const delLevel = useDeleteMembershipLevel();
  const changeLevel = useUpdateMemberLevel(); const changeStatus = useUpdateMemberStatus(); const changeBooking = useUpdateBookingStatus();
  const invalidate = (key: readonly unknown[]) => qc.invalidateQueries({ queryKey: key });
  if (userLoading) return <Shell><main className="mx-auto max-w-7xl px-5 py-10"><Loader /></main></Shell>;
  if (!user || user.role !== 'ADMIN') return <Shell><main className="mx-auto max-w-xl px-5 py-16 text-center"><div className="soft-card p-10"><ShieldCheck className="mx-auto text-[#c9a66b]" size={38} /><h1 className="mt-4 font-display text-3xl">Akses khusus tim Romi.</h1><p className="mt-3 text-sm text-[#76676a]">Masuk menggunakan akun admin untuk mengelola salon.</p><Action className="mt-6" onClick={() => setPath('/login')}>Masuk sebagai admin</Action></div></main></Shell>;
  const stateFor = (q: { isLoading: boolean; isError: boolean; refetch: () => unknown; data?: unknown }, content: ReactNode) => q.isLoading ? <Loader /> : q.isError ? <Notice retry={() => void q.refetch()}>Informasi belum berhasil dimuat.</Notice> : content;
  const nav = [{ id: 'overview', label: 'Ringkasan', icon: LayoutDashboard }, { id: 'services', label: 'Layanan', icon: Scissors }, { id: 'levels', label: 'Membership', icon: Crown }, { id: 'members', label: 'Member', icon: UsersRound }, { id: 'bookings', label: 'Reservasi', icon: CalendarDays }, { id: 'transactions', label: 'Transaksi', icon: Banknote }];
  const exportCsv = () => {
    const rows = (transactions.data || []).map((t) => [t.bookingId, t.memberName, t.serviceName, t.amount, t.discountAmount, t.finalAmount, t.status, t.createdAt]);
    const csv = [['ID Reservasi', 'Nama Member', 'Layanan', 'Harga', 'Diskon', 'Total', 'Status', 'Waktu'], ...rows].map((r) => r.map((x) => `"${String(x ?? '').replaceAll('"', '""')}"`).join(',')).join('\n');
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' })); a.download = 'transaksi-romi-salon.csv'; a.click(); URL.revokeObjectURL(a.href);
  };
  const changeBookingStatus = (id: string, status: 'CONFIRMED' | 'COMPLETED' | 'CANCELLED') => changeBooking.mutate({ bookingId: id, data: { status } }, { onSuccess: () => { setMessage('Status reservasi diperbarui.'); invalidate(getGetAdminBookingsQueryKey()); invalidate(getGetAdminDashboardQueryKey()); invalidate(getGetAdminTransactionsQueryKey()); }, onError: () => setMessage('Status reservasi belum berhasil diperbarui.') });
  const titles: Record<string, string> = { overview: 'Ringkasan', services: 'Layanan salon', levels: 'Tingkat membership', members: 'Daftar member', bookings: 'Reservasi', transactions: 'Transaksi' };
  return <Shell><main className="min-h-[calc(100dvh-150px)] bg-[#f6f0e8]"><div className="mx-auto max-w-[1440px] lg:grid lg:grid-cols-[240px_1fr]"><aside className="hidden min-h-[calc(100dvh-80px)] bg-[#3b1f2b] p-5 text-[#faf6f0] lg:block"><div className="mb-7 px-3 pt-3"><div className="eyebrow text-[#d1b27b]">Ruang pengelola</div><div className="mt-2 font-display text-2xl">Romi Salon</div></div><nav className="grid gap-1">{nav.map((n) => <button key={n.id} data-testid={`admin-tab-${n.id}`} onClick={() => setTab(n.id)} className={cx('flex items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition', tab === n.id ? 'bg-[#faf6f0] text-[#3b1f2b]' : 'text-[#eadccf]/75 hover:bg-white/10')}><n.icon size={17} />{n.label}</button>)}</nav><div className="mt-12 rounded-2xl border border-white/10 p-4"><div className="text-sm font-medium">{user.name}</div><div className="mt-1 text-xs text-[#eadccf]/60">Pengelola</div><Link href="/" className="mt-4 inline-flex text-xs text-[#d5b77f]">Lihat tampilan salon <ArrowRight size={13} className="ml-1" /></Link></div></aside>
      <section className="px-5 py-6 sm:px-8 lg:px-10"><div className="mb-7 flex flex-wrap items-center justify-between gap-4"><div><div className="eyebrow">Panel pengelolaan · WIB</div><h1 className="mt-2 font-display text-3xl text-[#3b1f2b]">{titles[tab]}</h1></div><div className="flex items-center gap-2"><select data-testid="admin-mobile-tabs" className="h-10 rounded-xl border border-[#dfd3c4] bg-[#faf6f0] px-3 text-sm lg:hidden" value={tab} onChange={(e) => setTab(e.target.value)}>{nav.map((n) => <option value={n.id} key={n.id}>{n.label}</option>)}</select><span className="hidden rounded-full bg-[#e5ede3] px-3 py-2 text-xs font-semibold text-[#55785a] sm:inline-flex">● Sistem aktif</span></div></div>{message && <div role="status" className="mb-5 rounded-xl bg-[#e6eee5] p-3 text-sm text-[#486d4b]">{message}</div>}
      {tab === 'overview' && stateFor(dash, <div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[{ l: 'Pendapatan hari ini', v: rupiah(dash.data?.todayRevenue), i: Banknote }, { l: 'Pendapatan bulan ini', v: rupiah(dash.data?.monthRevenue), i: ChartNoAxesCombined }, { l: 'Total transaksi', v: (dash.data?.transactionCount ?? 0).toLocaleString('id-ID'), i: CreditCard }, { l: 'Member baru', v: (dash.data?.newMembers ?? 0).toLocaleString('id-ID'), i: UsersRound }].map((m) => <div className="soft-card p-5" key={m.l}><div className="flex justify-between text-sm text-[#78696a]">{m.l}<m.i size={17} className="text-[#b18a53]" /></div><div className="mt-4 font-display text-2xl text-[#3b1f2b]">{m.v}</div></div>)}</div><div className="mt-6 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="soft-card p-6"><div className="flex items-center justify-between"><h2 className="font-display text-2xl">Pergerakan pendapatan</h2><span className="text-xs text-[#88777a]">IDR</span></div><div className="mt-8 flex h-52 items-end gap-3 border-b border-l border-[#e9ded1] px-3">{(dash.data?.revenueTrend || []).map((v, i) => { const max = Math.max(1, ...(dash.data?.revenueTrend || []).map((x) => x.amount)); return <div key={v.label} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div title={rupiah(v.amount)} className="w-full max-w-12 rounded-t-lg bg-[#c9a66b] transition-all hover:bg-[#3b1f2b]" style={{ height: `${Math.max(5, v.amount / max * 100)}%` }} /><span className="text-[10px] text-[#88777a]">{v.label}</span></div>; })}</div></div><div className="soft-card p-6"><h2 className="font-display text-2xl">Layanan favorit</h2><div className="mt-5 grid gap-3">{(dash.data?.topServices || []).map((s, i) => <div key={s} className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-full bg-[#f2e7d8] text-xs font-semibold text-[#8c6e45]">0{i + 1}</span><span className="text-sm">{s}</span></div>)}</div></div></div><div className="mt-6 soft-card p-6"><h2 className="font-display text-2xl">Reservasi berikutnya</h2><div className="mt-4 grid gap-3 md:grid-cols-2">{dash.data?.upcomingBookings?.map((b) => <div key={b.id} className="rounded-xl bg-[#f5eee5] p-4"><div className="font-semibold">{b.memberName} · {b.serviceName}</div><div className="mt-1 text-xs text-[#817174]">{dateId(b.startTime)}</div></div>)}</div></div></div>)}
      {tab === 'services' && <div>{stateFor(services, <div><div className="mb-4 flex justify-end"><Action kind="gold" onClick={() => setModal({ kind: 'service' })}><Plus size={16} /> Tambah layanan</Action></div><div className="soft-card overflow-hidden">{services.data?.length ? services.data.map((s) => <div key={s.id} className="flex flex-wrap items-center justify-between gap-4 border-b border-[#eee4d8] p-5 last:border-0"><div><div className="font-semibold">{s.name}<span className={cx('ml-2 rounded-full px-2 py-1 text-[10px]', s.isActive ? 'bg-[#e4eee2] text-[#4e7551]' : 'bg-[#f6e4e0] text-[#a14f49]')}>{s.isActive ? 'Aktif' : 'Nonaktif'}</span></div><div className="mt-1 text-xs text-[#857578]">{s.category} · {s.durationMin} menit · {rupiah(s.price)}</div></div><div className="flex gap-2"><Action kind="outline" onClick={() => setModal({ kind: 'service', item: s })}><Pencil size={14} /> Ubah</Action><Action kind="danger" onClick={() => { if (confirm(`Hapus layanan ${s.name}?`)) delService.mutate({ serviceId: s.id }, { onSuccess: () => invalidate(getGetAdminServicesQueryKey()), onError: () => setMessage('Layanan tidak dapat dihapus.') }); }}><Trash2 size={14} /></Action></div></div>) : <div className="p-8 text-sm text-[#76676a]">Belum ada layanan. Tambahkan layanan pertama.</div>}</div></div>)}</div>}
      {tab === 'levels' && <div>{stateFor(levels, <div><div className="mb-4 flex justify-end"><Action kind="gold" onClick={() => setModal({ kind: 'level' })}><Plus size={16} /> Tambah tingkat</Action></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{(levels.data || []).map((l) => <article key={l.id} className="soft-card p-6"><div className="flex justify-between"><span className="eyebrow">{l.discountPercent}% diskon</span><span className="text-xs text-[#89787b]">Urutan {l.sortOrder}</span></div><h3 className="mt-3 font-display text-2xl">{l.name}</h3><p className="mt-2 text-sm text-[#76676a]">Mulai {rupiah(l.minSpending)}</p><ul className="mt-4 grid gap-2 text-xs text-[#69585d]">{l.benefits.map((b) => <li key={b}>• {b}</li>)}</ul><div className="mt-5 flex gap-2"><Action kind="outline" className="flex-1" onClick={() => setModal({ kind: 'level', item: l })}><Pencil size={14} /> Ubah</Action><Action kind="danger" onClick={() => { if (confirm(`Hapus tingkat ${l.name}?`)) delLevel.mutate({ levelId: l.id }, { onSuccess: () => invalidate(getGetMembershipLevelsQueryKey()), onError: () => setMessage('Tingkat tidak dapat dihapus.') }); }}><Trash2 size={14} /></Action></div></article>)}</div></div>)}</div>}
      {tab === 'members' && <div>{stateFor(members, <div><div className="mb-4 flex items-center gap-3"><label className="relative flex-1"><Search size={16} className="absolute left-4 top-3.5 text-[#877578]" /><input data-testid="input-member-search" className="h-12 w-full rounded-xl border border-[#dfd3c4] bg-[#faf6f0] pl-11 pr-4 text-sm outline-none focus:border-[#c9a66b]" placeholder="Cari nama, email, atau nomor telepon…" value={search} onChange={(e) => setSearch(e.target.value)} /></label></div><div className="soft-card overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-[#f2e9de] text-xs text-[#796b6d]"><tr>{['Member', 'Tingkat', 'Total perawatan', 'Poin', 'Status', 'Aksi'].map((x) => <th key={x} className="px-4 py-3 font-semibold">{x}</th>)}</tr></thead><tbody>{(members.data || []).map((m) => <tr key={m.id} className="border-t border-[#eee4d8]"><td className="px-4 py-4"><div className="font-semibold">{m.name}</div><div className="text-xs text-[#867679]">{m.email} · {m.phone}</div></td><td className="px-4 py-4"><select aria-label={`Tingkat ${m.name}`} value={m.levelId} onChange={(e) => changeLevel.mutate({ userId: m.id, data: { levelId: e.target.value } }, { onSuccess: () => invalidate(getGetAdminMembersQueryKey(params)), onError: () => setMessage('Tingkat member belum berhasil diubah.') })} className="rounded-lg border border-[#dfd3c4] bg-white px-2 py-2">{(levels.data || []).map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}</select></td><td className="px-4 py-4">{rupiah(m.totalSpending)}</td><td className="px-4 py-4">{m.points.toLocaleString('id-ID')}</td><td className="px-4 py-4"><span className={cx('rounded-full px-2 py-1 text-xs', m.isActive ? 'bg-[#e4eee2] text-[#4e7551]' : 'bg-[#f6e4e0] text-[#a14f49]')}>{m.isActive ? 'Aktif' : 'Nonaktif'}</span></td><td className="px-4 py-4"><Action kind="outline" onClick={() => changeStatus.mutate({ userId: m.id, data: { isActive: !m.isActive } }, { onSuccess: () => invalidate(getGetAdminMembersQueryKey(params)), onError: () => setMessage('Status member belum berhasil diperbarui.') })}>{m.isActive ? 'Nonaktifkan' : 'Aktifkan'}</Action></td></tr>)}</tbody></table>{!members.data?.length && <div className="p-8 text-center text-sm text-[#76676a]">Member belum ditemukan.</div>}</div></div>)}</div>}
      {tab === 'bookings' && <div>{stateFor(bookings, <div><div className="mb-4 flex max-w-xs items-center gap-3"><Field label="Saring tanggal (WIB)" type="date" value={dateFilter} onChange={(e) => setDateFilter(e.target.value)} /></div><div className="soft-card overflow-x-auto"><table className="w-full min-w-[770px] text-left text-sm"><thead className="bg-[#f2e9de] text-xs text-[#796b6d]"><tr>{['Reservasi', 'Member', 'Jadwal', 'Pembayaran', 'Total', 'Status & tindakan'].map((x) => <th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{(bookings.data || []).map((b) => <tr key={b.id} className="border-t border-[#eee4d8]"><td className="px-4 py-4"><b>{b.serviceName}</b><div className="text-xs text-[#867679]">{b.bookingCode}</div></td><td className="px-4 py-4">{b.memberName}</td><td className="px-4 py-4">{dateId(b.startTime)}</td><td className="px-4 py-4">{statusId(b.paymentStatus)}</td><td className="px-4 py-4">{rupiah(b.finalAmount)}</td><td className="px-4 py-4"><select aria-label={`Status ${b.bookingCode}`} value={b.status} onChange={(e) => changeBookingStatus(b.id, e.target.value as 'CONFIRMED' | 'COMPLETED' | 'CANCELLED')} className="rounded-lg border border-[#dfd3c4] bg-white px-2 py-2"><option value="PENDING_PAYMENT" disabled>Menunggu pembayaran</option><option value="CONFIRMED">Terkonfirmasi</option><option value="COMPLETED">Selesai</option><option value="CANCELLED">Dibatalkan</option></select></td></tr>)}</tbody></table>{!bookings.data?.length && <div className="p-8 text-center text-sm text-[#76676a]">Tidak ada reservasi pada tanggal tersebut.</div>}</div></div>)}</div>}
      {tab === 'transactions' && <div>{stateFor(transactions, <div><div className="mb-4 flex justify-end"><Action kind="outline" onClick={exportCsv}><Download size={15} /> Ekspor CSV</Action></div><div className="soft-card overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[#f2e9de] text-xs text-[#796b6d]"><tr>{['Member', 'Layanan', 'Harga', 'Diskon', 'Total', 'Status', 'Tanggal'].map((x) => <th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{(transactions.data || []).map((t) => <tr key={t.id} className="border-t border-[#eee4d8]"><td className="px-4 py-4">{t.memberName}</td><td className="px-4 py-4">{t.serviceName}</td><td className="px-4 py-4">{rupiah(t.amount)}</td><td className="px-4 py-4">{rupiah(t.discountAmount)}</td><td className="px-4 py-4 font-semibold">{rupiah(t.finalAmount)}</td><td className="px-4 py-4">{t.status}</td><td className="px-4 py-4">{dateId(t.createdAt)}</td></tr>)}</tbody></table>{!transactions.data?.length && <div className="p-8 text-center text-sm text-[#76676a]">Belum ada transaksi.</div>}</div></div>)}</div>}
      </section></div></main>{modal && <AdminForm modal={modal} onClose={() => setModal(null)} onSave={(data) => { if (modal.kind === 'service') { const service = data as ServiceInput; if (modal.item) editService.mutate({ serviceId: modal.item.id, data: service }, { onSuccess: () => { invalidate(getGetAdminServicesQueryKey()); setModal(null); }, onError: () => setMessage('Perubahan layanan belum tersimpan.') }); else addService.mutate({ data: service }, { onSuccess: () => { invalidate(getGetAdminServicesQueryKey()); invalidate(getGetSalonOverviewQueryKey()); setModal(null); }, onError: () => setMessage('Layanan belum berhasil ditambahkan.') }); } else { const level = data as LevelInput; if (modal.item) editLevel.mutate({ levelId: modal.item.id, data: level }, { onSuccess: () => { invalidate(getGetMembershipLevelsQueryKey()); invalidate(getGetSalonOverviewQueryKey()); setModal(null); }, onError: () => setMessage('Perubahan tingkat belum tersimpan.') }); else addLevel.mutate({ data: level }, { onSuccess: () => { invalidate(getGetMembershipLevelsQueryKey()); invalidate(getGetSalonOverviewQueryKey()); setModal(null); }, onError: () => setMessage('Tingkat belum berhasil ditambahkan.') }); } }} />}</Shell>;
}

function AdminForm({ modal, onClose, onSave }: { modal: { kind: 'service' | 'level'; item?: SalonService | MembershipLevel }; onClose: () => void; onSave: (data: ServiceInput | LevelInput) => void }) {
  const service = modal.kind === 'service' ? modal.item as SalonService | undefined : undefined;
  const level = modal.kind === 'level' ? modal.item as MembershipLevel | undefined : undefined;
  const [values, setValues] = useState({ name: service?.name || level?.name || '', description: service?.description || '', durationMin: String(service?.durationMin ?? 60), price: String(service?.price ?? ''), imageUrl: service?.imageUrl || '', category: service?.category || 'Perawatan', isActive: service?.isActive ?? true, minSpending: String(level?.minSpending ?? ''), discountPercent: String(level?.discountPercent ?? 0), badgeColor: level?.badgeColor || '#C9A66B', benefits: level?.benefits.join('\n') || '', sortOrder: String(level?.sortOrder ?? 0) });
  const set = (k: string, v: string | boolean) => setValues((s) => ({ ...s, [k]: v }));
  const submit = (e: FormEvent) => { e.preventDefault(); if (modal.kind === 'service') onSave({ name: values.name, description: values.description, durationMin: Number(values.durationMin), price: Number(values.price), imageUrl: values.imageUrl || null, category: values.category, isActive: values.isActive }); else onSave({ name: values.name, minSpending: Number(values.minSpending), discountPercent: Number(values.discountPercent), badgeColor: values.badgeColor, benefits: values.benefits.split('\n').map((x) => x.trim()).filter(Boolean), sortOrder: Number(values.sortOrder) }); };
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#25131c]/60 p-4"><form onSubmit={submit} className="max-h-[90dvh] w-full max-w-xl overflow-auto rounded-3xl bg-[#faf6f0] p-7 shadow-2xl"><div className="mb-6 flex items-start justify-between"><div><div className="eyebrow">{modal.item ? 'Perbarui data' : 'Data baru'}</div><h2 className="mt-2 font-display text-3xl">{modal.kind === 'service' ? service ? 'Ubah layanan' : 'Tambah layanan' : level ? 'Ubah tingkat' : 'Tambah tingkat'}</h2></div><button type="button" aria-label="Tutup" onClick={onClose}><X /></button></div><div className="grid gap-4 sm:grid-cols-2"><Field label="Nama" required minLength={2} value={values.name} onChange={(e) => set('name', e.target.value)} />{modal.kind === 'service' ? <><Field label="Kategori" required value={values.category} onChange={(e) => set('category', e.target.value)} /><Field label="Durasi (menit)" type="number" min={10} required value={values.durationMin} onChange={(e) => set('durationMin', e.target.value)} /><Field label="Harga (Rp)" type="number" min={0} required value={values.price} onChange={(e) => set('price', e.target.value)} /><Field label="URL gambar (opsional)" value={values.imageUrl} onChange={(e) => set('imageUrl', e.target.value)} /><label className="flex items-center gap-3 text-sm sm:col-span-2"><input type="checkbox" checked={values.isActive} onChange={(e) => set('isActive', e.target.checked)} />Layanan aktif dan dapat dipesan</label><label className="grid gap-2 text-sm sm:col-span-2">Deskripsi<textarea required rows={3} value={values.description} onChange={(e) => set('description', e.target.value)} className="rounded-xl border border-[#dfd3c4] bg-white p-3 outline-none focus:border-[#c9a66b]" /></label></> : <><Field label="Minimal belanja (Rp)" type="number" min={0} required value={values.minSpending} onChange={(e) => set('minSpending', e.target.value)} /><Field label="Diskon (%)" type="number" min={0} max={100} required value={values.discountPercent} onChange={(e) => set('discountPercent', e.target.value)} /><Field label="Warna badge" type="color" value={values.badgeColor} onChange={(e) => set('badgeColor', e.target.value)} /><Field label="Urutan" type="number" min={0} value={values.sortOrder} onChange={(e) => set('sortOrder', e.target.value)} /><label className="grid gap-2 text-sm sm:col-span-2">Manfaat (satu per baris)<textarea rows={4} value={values.benefits} onChange={(e) => set('benefits', e.target.value)} className="rounded-xl border border-[#dfd3c4] bg-white p-3 outline-none focus:border-[#c9a66b]" /></label></>}</div><div className="mt-6 flex justify-end gap-2"><Action kind="outline" onClick={onClose}>Batal</Action><Action type="submit" kind="gold">Simpan</Action></div></form></div>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}
function Router() {
  return <RoutedErrorBoundary><Switch><Route path="/" component={Home} /><Route path="/login"><AuthPage mode="login" /></Route><Route path="/register"><AuthPage mode="register" /></Route><Route path="/member" component={MemberPage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch></RoutedErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={client}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;
